def render(c, site, path_self, path_other_lang_url):
    esc=lambda s:s.replace('&','&amp;').replace('<','&lt;')
    def entity():
        e=c['entity']
        rows=[e[0],e[1],e[2],e[3]]
        out='<p class="ent">'+'<br>'.join(esc(r) for r in rows[:3])+'<br><a href="mailto:contact@reasonconcept.gr">contact@reasonconcept.gr</a>'
        if GEMI: out+='<br>'+esc(c['gemi'])+esc(GEMI)
        return out+'</p>'
    body=''
    for sec in c['sections']:
        body+='<h2>'+esc(sec[0])+'</h2>'
        parts=sec[1:]
        body+=''.join('<p>'+esc(t)+'</p>' for t in parts[0])
        if len(parts)>=2:
            if parts[1]=='CONTROLLER': body+=entity()
            else: body+='<ul>'+''.join('<li>'+esc(t)+'</li>' for t in parts[1])+'</ul>'
        if len(parts)>=3: body+=''.join('<p>'+esc(t)+'</p>' for t in parts[2])
    L=c['lang']; other_label,other_href=c['other']
    home='/' if L=='en' else '/el/'
    url=site+path_self
    alt_en=site+'/privacy/'; alt_el=site+'/el/privacy/'
    return f'''<!doctype html><html lang="{L}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{esc(c['title'])}</title><meta name="description" content="{esc(c['h1'])} - Reason Fitness Concept, Pandorou 36, Petralona, Athens.">
<link rel="canonical" href="{url}"><link rel="alternate" hreflang="en" href="{alt_en}"><link rel="alternate" hreflang="el" href="{alt_el}"><link rel="alternate" hreflang="x-default" href="{alt_en}">
<link rel="icon" href="/favicon.ico" sizes="48x48"><link rel="icon" type="image/png" sizes="192x192" href="/favicon-192.png"><link rel="apple-touch-icon" href="/apple-touch-icon.png">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:wght@300;500&family=Source+Serif+4:wght@300;500&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
<style>
:root{{--bg:#F6F1E6;--ink:#26262A;--mute:#5E5A52;--accent:#2B3490}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif;line-height:1.7;font-size:16px}}
.wrap{{max-width:760px;margin:0 auto;padding:28px 20px 80px}}
.top{{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:15px;font-weight:500;padding-bottom:28px;border-bottom:1px solid rgba(38,38,42,.1)}}
a{{color:var(--accent)}}.top a{{color:var(--ink);text-decoration:none;padding:8px 0}}
h1{{font-family:Fraunces,'Source Serif 4',serif;font-weight:300;font-size:clamp(34px,6vw,52px);line-height:1.1;margin:40px 0 8px}}
.brand{{font-size:12px;letter-spacing:.2em;color:var(--accent);font-weight:600}}.upd{{color:var(--mute);font-size:14px;margin:0 0 24px}}
h2{{font-family:Fraunces,'Source Serif 4',serif;font-weight:500;font-size:22px;margin:34px 0 6px}}
p{{margin:8px 0}}ul{{margin:8px 0;padding-left:22px}}li{{margin:4px 0}}.ent{{background:#FBF7EE;border:1px solid #E4DAC7;border-radius:16px;padding:16px 20px}}
.foot{{margin-top:40px;color:var(--mute);font-size:14px}}
</style></head><body><div class="wrap">
<div class="top"><a href="{home}">{esc(c['back'])}</a><a href="{other_href}" hreflang="{'el' if L=='en' else 'en'}">{esc(other_label)}</a></div>
<div class="brand" style="margin-top:36px">{esc(c['brand'])}</div><h1>{esc(c['h1'])}</h1><p class="upd">{esc(c['updated'])}</p>
{body}<p class="foot">{esc(c['foot'])}</p></div></body></html>'''
